import { Button, Input, LinkButton } from "@cloudflare/kumo";
import { useEffect, useState } from "react";

import { formatClientError, m1Fetch } from "../lib/m1-client";
import { FormError, FormStatus, M1Layout } from "./m1-layout";

type InvitationDetails = {
  email: string;
  expiresAt: number;
  name: string | null;
  status: "pending" | "claimed";
};

export function InvitationPage({ token }: Readonly<{ token: string }>) {
  const [invitation, setInvitation] = useState<InvitationDetails>();
  const [email, setEmail] = useState("");
  const [name, setName] = useState("");
  const [password, setPassword] = useState("");
  const [isLoading, setIsLoading] = useState(true);
  const [isPending, setIsPending] = useState(false);
  const [error, setError] = useState<string>();
  const [accepted, setAccepted] = useState(false);

  useEffect(() => {
    let active = true;
    void m1Fetch<InvitationDetails>(`/invitations/${encodeURIComponent(token)}`).then(
      (details) => {
        if (!active) return;
        setInvitation(details);
        setEmail(details.email);
        setName(details.name ?? "");
        setIsLoading(false);
      },
      (loadError) => {
        if (!active) return;
        setError(formatClientError(loadError));
        setIsLoading(false);
      },
    );
    return () => {
      active = false;
    };
  }, [token]);

  async function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!invitation) return;
    setError(undefined);
    setIsPending(true);
    try {
      await m1Fetch(`/invitations/${encodeURIComponent(token)}/accept`, {
        body: JSON.stringify({ email, name, password }),
        method: "POST",
      });
      setAccepted(true);
    } catch (submitError) {
      setError(formatClientError(submitError));
    } finally {
      setIsPending(false);
    }
  }

  if (isLoading) {
    return (
      <M1Layout
        description="Checking the invitation and its expiry before showing the account form."
        eyebrow="Invitation"
        title="One moment."
      >
        <p className="text-sm text-kumo-subtle" role="status">
          Loading invitation...
        </p>
      </M1Layout>
