      invitationId,
      userId,
    );
}

async function completeBootstrapDomain(
  database: D1Database,
  state: BootstrapState,
  user: ManagedUser,
  principalId: string,
  now: number,
) {
  const existingRoot = await createDb(database)
    .select({ principalId: systemRoleGrants.principalId })
    .from(systemRoleGrants)
    .innerJoin(systemRoles, eq(systemRoles.id, systemRoleGrants.roleId))
    .innerJoin(principals, eq(principals.id, systemRoleGrants.principalId))
    .innerJoin(humanPrincipals, eq(humanPrincipals.principalId, principals.id))
    .where(
      and(
        eq(systemRoles.key, "root"),
        isNull(systemRoleGrants.revokedAt),
        eq(principals.type, "human"),
        eq(principals.status, "active"),
        eq(humanPrincipals.status, "active"),
        eq(humanPrincipals.disabled, false),
      ),
    )
    .get();
  if (existingRoot && existingRoot.principalId !== principalId) throw new M1Error(409);

  const email = state.email ?? normalizeEmail(user.email);
  const eventId = `bootstrap:completed:${state.reservation_id ?? principalId}`;
  const results = await database.batch([
    database
      .prepare(
        `UPDATE bootstrap_state
            SET status = 'completed', principal_id = ?, completed_at = ?, updated_at = ?
          WHERE id = 1
            AND status IN ('reserved', 'user-created')
            AND reservation_id = ?
            AND email = ?
            AND user_id = ?
          RETURNING id`,
      )
      .bind(principalId, now, now, state.reservation_id, email, user.id),
    grantBootstrapRoleStatement(database, state.reservation_id ?? "", user.id, principalId, now),
    auditStatementWhen(
      database,
      eventId,
      "bootstrap.completed",
      null,
      principalId,
      user.id,
      { email },
      now,
      "SELECT 1 FROM bootstrap_state WHERE id = 1 AND status = 'completed' AND reservation_id = ? AND user_id = ?",
      [state.reservation_id, user.id],
    ),
    outboxStatementWhen(
      database,
      `bootstrap:completed:outbox:${state.reservation_id ?? principalId}`,
      "bootstrap.completed",
      "bootstrap",
      "1",
      { principalId, userId: user.id },
      now,
      "SELECT 1 FROM bootstrap_state WHERE id = 1 AND status = 'completed' AND reservation_id = ? AND user_id = ?",
      [state.reservation_id, user.id],
    ),
  ]);
  if (!results[0]?.results.length) throw new M1Error(409);
}

async function reserveBootstrap(
  environment: AuthEnvironment,
  body: BootstrapTokenBody,
  request: Request,
) {
  await enforceRateLimit(environment, request, "bootstrap-reserve", 50, 60);
  await requireBootstrapToken(environment, body);
  const state = await getBootstrapState(environment.DB);
  if (state.status === "completed") throw new M1Error(404);
  if (state.status !== "uninitialized") {
    if (!state.reservation_id) throw new M1Error(500);
    return { reservationId: state.reservation_id, status: state.status };
  }

  const reservationId = crypto.randomUUID();
  const now = Date.now();
  const results = await environment.DB.batch([
    environment.DB.prepare(
      `UPDATE bootstrap_state
              SET status = 'reserved', reservation_id = ?, reserved_at = ?, updated_at = ?
            WHERE id = 1 AND status = 'uninitialized'
            RETURNING reservation_id, status`,
    ).bind(reservationId, now, now),
    auditStatementWhen(
      environment.DB,
      `bootstrap:reserved:${reservationId}`,
      "bootstrap.reserved",
      null,
      null,
      null,
      {},
      now,
      "SELECT 1 FROM bootstrap_state WHERE id = 1 AND status = 'reserved' AND reservation_id = ? AND reserved_at = ?",
      [reservationId, now],
    ),
    outboxStatementWhen(
      environment.DB,
      `bootstrap:reserved:outbox:${reservationId}`,
      "bootstrap.reserved",
      "bootstrap",
      "1",
      { reservationId },
      now,
      "SELECT 1 FROM bootstrap_state WHERE id = 1 AND status = 'reserved' AND reservation_id = ? AND reserved_at = ?",
      [reservationId, now],
    ),
  ]);
  const reserved = results[0]?.results[0] as
    | { reservation_id: string; status: BootstrapStatus }
    | undefined;

  if (!reserved) {
    const racedState = await getBootstrapState(environment.DB);
    if (racedState.status === "completed" || !racedState.reservation_id) throw new M1Error(409);
    return { reservationId: racedState.reservation_id, status: racedState.status };
  }

  return { reservationId, status: reserved.status };
}

async function completeBootstrap(
  environment: AuthEnvironment,
  auth: AuthInstance,
  body: BootstrapCompleteBody,
  request: Request,
) {
  await enforceRateLimit(environment, request, "bootstrap-complete", 50, 60);
  await requireBootstrapToken(environment, body);
  const state = await getBootstrapState(environment.DB);
  if (state.status === "completed") {
    if (state.email && normalizeEmail(body.email) !== state.email) throw new M1Error(409);
    return { status: state.status, userId: state.user_id };
  }
  if (state.status === "uninitialized" || !state.reservation_id) throw new M1Error(409);
  if (body.reservationId && body.reservationId !== state.reservation_id) throw new M1Error(409);

  const email = normalizeEmail(body.email);
  if (state.email && state.email !== email) throw new M1Error(409);

  const context = await auth.$context;
  if (
    body.password.length < context.password.config.minPasswordLength ||
    body.password.length > context.password.config.maxPasswordLength
  ) {
    throw new M1Error(400);
  }

  if (!state.email) {
    const claimedEmail = await environment.DB.prepare(
      `UPDATE bootstrap_state
            SET email = ?, updated_at = ?
          WHERE id = 1
            AND status = 'reserved'
            AND reservation_id = ?
            AND (email IS NULL OR email = ?)
          RETURNING email`,
    )
      .bind(email, Date.now(), state.reservation_id, email)
      .first<{ email: string }>();
    if (!claimedEmail) {
      const racedState = await getBootstrapState(environment.DB);
      if (racedState.email !== email) throw new M1Error(409);
    }
  }

  const user = await ensureControlledUser(
    auth,
    email,
    normalizeName(body.name, email),
    body.password,
    state.user_id,
    false,
    state.reserved_at,
  );
  const marked = await environment.DB.prepare(
    `UPDATE bootstrap_state
          SET status = 'user-created', user_id = ?, user_created_at = COALESCE(user_created_at, ?), updated_at = ?
        WHERE id = 1
          AND status IN ('reserved', 'user-created')
          AND reservation_id = ?
          AND email = ?
          AND (user_id IS NULL OR user_id = ?)
        RETURNING user_id`,
  )
    .bind(user.id, Date.now(), Date.now(), state.reservation_id, email, user.id)
    .first<{ user_id: string }>();
  if (!marked) {
    const racedState = await getBootstrapState(environment.DB);
    if (racedState.user_id !== user.id) throw new M1Error(409);
  }

  const markedState = await getBootstrapState(environment.DB);
  const principalId = await ensureHumanPrincipal(environment.DB, user.id, Date.now());
  await completeBootstrapDomain(environment.DB, markedState, user, principalId, Date.now());
  await sendVerificationEmail(auth, user);

  return { principalId, status: "completed" as const, userId: user.id };
}

async function readInvitation(database: D1Database, tokenHash: string) {
  const row = await createDb(database)
    .select()
    .from(invitations)
    .where(eq(invitations.tokenHash, tokenHash))
    .get();

  return row
    ? {
        id: row.id,
        token_hash: row.tokenHash,
        email: row.email,
        name: row.name,
        status: row.status,
        expires_at: row.expiresAt,
        invited_by_principal_id: row.invitedByPrincipalId,
        claimed_user_id: row.claimedUserId,
        claimed_principal_id: row.claimedPrincipalId,
        system_role_keys: row.systemRoleKeys,
        claimed_at: row.claimedAt,
      }
    : undefined;
}

async function markExpired(database: D1Database, invitationId: string, now: number) {
  await createDb(database)
    .update(invitations)
    .set({ status: "expired", updatedAt: now })
    .where(
      and(
        eq(invitations.id, invitationId),
        inArray(invitations.status, ["pending", "claimed"]),
        lte(invitations.expiresAt, now),
      ),
    )
    .run();
}

async function createInvitation(
  environment: AuthEnvironment,
  actor: Actor,
  body: InvitationCreateBody,
  request: Request,
) {
  await enforceRateLimit(environment, request, "invitation-create", 30, 60);
  const email = normalizeEmail(body.email);
  const name = body.name ? normalizeName(body.name, email) : null;
  const requestedRoleKeys = await validateRoleKeys(environment.DB, body.systemRoleKeys ?? []);
  const existingMapping = await createDb(environment.DB)
    .select({ userId: humanPrincipals.userId })
    .from(humanPrincipals)
    .innerJoin(principals, eq(principals.id, humanPrincipals.principalId))
    .innerJoin(user, eq(user.id, humanPrincipals.userId))
    .where(
      and(
        eq(user.email, email),
        eq(principals.status, "active"),
        eq(humanPrincipals.status, "active"),
        eq(humanPrincipals.disabled, false),
      ),
    )
    .get();
  if (existingMapping) throw new M1Error(409);

  const token = randomToken();
  const tokenHash = await sha256Base64Url(token);
  const invitationId = crypto.randomUUID();
  const now = Date.now();
  const requestedLifetime = body.expiresInSeconds ?? body.expiresIn ?? 60 * 60 * 24 * 7;
  const expiresAt = now + requestedLifetime * 1000;

  await environment.DB.batch([
    environment.DB.prepare(
      `INSERT INTO invitations
          (id, token_hash, email, name, status, expires_at, invited_by_principal_id, system_role_keys, created_at, updated_at)
         VALUES (?, ?, ?, ?, 'pending', ?, ?, ?, ?, ?)`,
    ).bind(
      invitationId,
      tokenHash,
      email,
      name,
      expiresAt,
      actor.principalId,
      JSON.stringify(requestedRoleKeys),
      now,
      now,
    ),
    auditStatement(
      environment.DB,
      `invitation:created:${invitationId}`,
      "invitation.created",
      actor.principalId,
      null,
      null,
      { email, expiresAt },
      now,
    ),
    outboxStatement(
      environment.DB,
      `invitation:created:outbox:${invitationId}`,
      "invitation.created",
      "invitation",
      invitationId,
      { email, expiresAt },
      now,
    ),
  ]);

  await sendInvitationEmail(environment, { email, expiresAt, name, token });
  return { email, expiresAt, id: invitationId, token };
}

async function getPublicInvitation(environment: AuthEnvironment, token: string, request: Request) {
  await enforceRateLimit(environment, request, "invitation-read", 60, 60);
  const invitation = await readInvitation(environment.DB, await sha256Base64Url(token));
  if (!invitation) throw new M1Error(404);
  const now = Date.now();
  if (
    (invitation.status === "pending" || invitation.status === "claimed") &&
    invitation.expires_at <= now
  ) {
    await markExpired(environment.DB, invitation.id, now);
    throw new M1Error(404);
  }
  if (invitation.status !== "pending" && invitation.status !== "claimed") throw new M1Error(404);
  return {
    email: invitation.email,
    expiresAt: invitation.expires_at,
    name: invitation.name,
    status: invitation.status,
  };
}

async function claimInvitationWithAuth(
  environment: AuthEnvironment,
  auth: AuthInstance,
  token: string,
  body: InvitationAcceptBody,
  request: Request,
) {
  await enforceRateLimit(environment, request, "invitation-accept", 30, 60);
  const invitation = await readInvitation(environment.DB, await sha256Base64Url(token));
  if (!invitation) throw new M1Error(404);
  const now = Date.now();
  const suppliedEmail = body.email ? normalizeEmail(body.email) : invitation.email;
  if (suppliedEmail !== invitation.email) throw new M1Error(400);
  const context = await auth.$context;
  if (
    body.password.length < context.password.config.minPasswordLength ||
    body.password.length > context.password.config.maxPasswordLength
  ) {
    throw new M1Error(400);
  }

  let current = invitation;
  if (current.status === "pending") {
    if (current.expires_at <= now) {
      await markExpired(environment.DB, current.id, now);
      throw new M1Error(404);
    }
    const claimed = await environment.DB.prepare(
      `UPDATE invitations
            SET status = 'claimed', claimed_at = ?, updated_at = ?
          WHERE id = ? AND status = 'pending' AND expires_at > ?
        RETURNING id, token_hash, email, name, status, expires_at,
                  invited_by_principal_id, claimed_user_id, claimed_principal_id, system_role_keys`,
    )
      .bind(now, now, current.id, now)
      .first<Invitation>();
    current = claimed ?? (await readInvitation(environment.DB, current.token_hash)) ?? current;
  }
  if (
    current.status === "pending" ||
    current.status === "expired" ||
    current.status === "revoked"
  ) {
    throw new M1Error(409);
  }
  if (current.expires_at <= now) {
    await markExpired(environment.DB, current.id, now);
    throw new M1Error(409);
  }
  if (current.status === "completed") throw new M1Error(409);

  const user = await ensureControlledUser(
    auth,
    current.email,
    normalizeName(body.name, current.name ?? current.email),
    body.password,
    current.claimed_user_id,
    Boolean(current.claimed_user_id),
    current.claimed_at,
  );
  const marked = await environment.DB.prepare(
    `UPDATE invitations
          SET claimed_user_id = ?, updated_at = ?
        WHERE id = ? AND status = 'claimed'
          AND (claimed_user_id IS NULL OR claimed_user_id = ?)
        RETURNING claimed_user_id`,
  )
    .bind(user.id, Date.now(), current.id, user.id)
    .first<{ claimed_user_id: string }>();
  if (!marked) {
    const racedInvitation = await readInvitation(environment.DB, current.token_hash);
    if (!racedInvitation || racedInvitation.claimed_user_id !== user.id) throw new M1Error(409);
    current = racedInvitation;
  } else {
    current = (await readInvitation(environment.DB, current.token_hash)) ?? current;
  }
  if (current.status !== "claimed") throw new M1Error(409);

  const principalId = await ensureHumanPrincipal(environment.DB, user.id, Date.now());
  const roleKeys = await validateRoleKeys(
    environment.DB,
    roleKeysFromStorage(current.system_role_keys),
  );
  const eventId = `invitation:completed:${current.id}`;
  const completedAt = Date.now();
  const statements = [
    environment.DB.prepare(
      `UPDATE invitations
          SET status = 'completed', claimed_principal_id = ?, completed_at = ?, updated_at = ?
          WHERE id = ? AND status = 'claimed' AND claimed_user_id = ?
            AND expires_at > ?
        RETURNING id`,
    ).bind(principalId, completedAt, completedAt, current.id, user.id, completedAt),
    ...roleKeys.map((roleKey) =>
      grantInvitationRoleStatement(
        environment.DB,
        current.id,
        user.id,
        principalId,
        roleKey,
        current.invited_by_principal_id,
        completedAt,
      ),
    ),
    auditStatementWhen(
      environment.DB,
      eventId,
      "invitation.completed",
      current.invited_by_principal_id,
      principalId,
      user.id,
      { email: current.email },
      completedAt,
      "SELECT 1 FROM invitations WHERE id = ? AND status = 'completed' AND claimed_user_id = ?",
      [current.id, user.id],
    ),
    outboxStatementWhen(
      environment.DB,
      `invitation:completed:outbox:${current.id}`,
      "invitation.completed",
      "invitation",
      current.id,
      { principalId, userId: user.id },
      completedAt,
      "SELECT 1 FROM invitations WHERE id = ? AND status = 'completed' AND claimed_user_id = ?",
      [current.id, user.id],
    ),
  ];
  const results = await environment.DB.batch(statements);
  const completionResult = results[0];
  if (!completionResult?.results.length) throw new M1Error(409);
  await sendVerificationEmail(auth, user);
  return {
    email: user.email,
    principalId,
    status: "accepted" as const,
    userId: user.id,
  };
}

async function resolveInvitationForRevoke(database: D1Database, identifier: string) {
  const db = createDb(database);
  const byId = await db
    .select({ id: invitations.id, status: invitations.status })
    .from(invitations)
    .where(eq(invitations.id, identifier))
    .get();
  if (byId) return byId;
  const tokenHash = await sha256Base64Url(identifier);
  return db
    .select({ id: invitations.id, status: invitations.status })
    .from(invitations)
    .where(eq(invitations.tokenHash, tokenHash))
    .get();
}

async function revokeInvitation(
  environment: AuthEnvironment,
  actor: Actor,
  identifier: string,
  request: Request,
) {
  await enforceRateLimit(environment, request, "invitation-revoke", 30, 60);
  const invitation = await resolveInvitationForRevoke(environment.DB, identifier);
  if (!invitation) throw new M1Error(404);
  const now = Date.now();
  const results = await environment.DB.batch([
    environment.DB.prepare(
      `UPDATE invitations
            SET status = 'revoked', revoked_at = ?, updated_at = ?
           WHERE id = ? AND status = 'pending'
           RETURNING id`,
    ).bind(now, now, invitation.id),
    auditStatementWhen(
      environment.DB,
      `invitation:revoked:${invitation.id}`,
      "invitation.revoked",
      actor.principalId,
      null,
      null,
      { invitationId: invitation.id },
      now,
      "SELECT 1 FROM invitations WHERE id = ? AND status = 'revoked' AND revoked_at = ?",
      [invitation.id, now],
    ),
    outboxStatementWhen(
      environment.DB,
      `invitation:revoked:outbox:${invitation.id}`,
      "invitation.revoked",
      "invitation",
      invitation.id,
      {},
      now,
      "SELECT 1 FROM invitations WHERE id = ? AND status = 'revoked' AND revoked_at = ?",
      [invitation.id, now],
    ),
  ]);
  if (!results[0]?.results.length) {
    const current = await resolveInvitationForRevoke(environment.DB, identifier);
    if (current?.status !== "revoked") throw new M1Error(409);

