          after: async (session) => {
            await recordAuthAudit(db, "auth.session_revoked", session.userId, {
              sessionId: session.id,
            });
          },
        },
      },
    },
    telemetry: {
      enabled: false,
    },
    trustedOrigins: [environment.BETTER_AUTH_URL],
  });
}

export type AuthInstance = ReturnType<typeof createAuth>;

